const { execSync } = require('child_process');
const fs = require('fs');

// The video contains a continuous morph transition generated by AI between:
// ROLLER COASTER -> WATER RIDE -> CUP & SAUCER -> BUMPER CARS
// Let's create an html file that displays frames 10, 20, 30, ..., 240 with their frame number
let html = '<!DOCTYPE html><html><head><style>body{background:#111;color:#fff;font-family:sans-serif;} .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;} img{width:100%;border-radius:4px;} .card{background:#222;padding:6px;border-radius:6px;}</style></head><body><h1>Frame Catalog</h1><div class="grid">';

for (let i = 1; i <= 240; i += 6) {
  const padded = String(i).padStart(3, '0');
  html += `<div class="card"><img src="/frames/coaster/frame_${padded}.webp"/><div>Frame ${i} (${Math.round((i/240)*100)}%)</div></div>`;
}

html += '</div></body></html>';
fs.writeFileSync('public/catalog.html', html);
console.log('Catalog created at public/catalog.html');
